description:
Write `final class Chars` with methods that treat text as Unicode characters (code points), never splitting an emoji or another character that needs two `char`s:

- `static int length(String s)`: the number of code points;
- `static String reverse(String s)`: the code points in reverse order;
- `static String truncate(String s, int max)`: at most `max` code points; if it had to cut, the last of those is replaced by `…` (so the result is still at most `max`); `max` below 1 throws `IllegalArgumentException`;
- `static Map<String, Integer> kinds(String s)`: counts of `"letter"`, `"digit"`, `"space"` and `"other"` code points, in a `TreeMap`, leaving out kinds with a count of 0.

starter.Chars.java:
import java.util.*;

public final class Chars {
    public static int length(String s) {
        return s.length();
    }

    public static String reverse(String s) {
        return new StringBuilder(s).reverse().toString();
    }

    public static String truncate(String s, int max) {
        return s.length() <= max ? s : s.substring(0, max);
    }

    public static Map<String, Integer> kinds(String s) {
        return new TreeMap<>();
    }
}

solution.Chars.java:
import java.util.*;

public final class Chars {
    public static int length(String s) {
        return s.codePointCount(0, s.length());
    }

    public static String reverse(String s) {
        int[] cps = s.codePoints().toArray();
        StringBuilder sb = new StringBuilder();
        for (int i = cps.length - 1; i >= 0; i--) sb.appendCodePoint(cps[i]);
        return sb.toString();
    }

    public static String truncate(String s, int max) {
        if (max < 1) throw new IllegalArgumentException("max must be at least 1");
        int[] cps = s.codePoints().toArray();
        if (cps.length <= max) return s;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < max - 1; i++) sb.appendCodePoint(cps[i]);
        return sb.append('…').toString();
    }

    public static Map<String, Integer> kinds(String s) {
        Map<String, Integer> out = new TreeMap<>();
        s.codePoints().forEach(cp -> {
            String kind = Character.isLetter(cp) ? "letter" : Character.isDigit(cp) ? "digit" : Character.isWhitespace(cp) ? "space" : "other";
            out.merge(kind, 1, Integer::sum);
        });
        return out;
    }
}

unitTests:
String s = "café 😀 42";

test("length counts characters", () -> {
    checkEq(Chars.length(s), 9);
    checkEq(Chars.length(""), 0);
});

test("reverse keeps emoji whole", () -> {
    checkEq(Chars.reverse("a😀b"), "b😀a");
    checkEq(Chars.reverse(s), "24 😀 éfac");
});

test("truncate", () -> {
    checkEq(Chars.truncate("hello", 10), "hello");
    checkEq(Chars.truncate("hello world", 5), "hell…");
    checkEq(Chars.truncate("😀😀😀", 2), "😀…");
    checkThrows(IllegalArgumentException.class, () -> Chars.truncate("x", 0));
});

test("kinds", () -> {
    checkEq(Chars.kinds(s).toString(), "{digit=2, letter=4, other=1, space=2}");
});

